#!/usr/bin/env python3
"""Generate concise AI Career Compass course artifacts from the frozen snapshot."""
from __future__ import annotations
import argparse, html, json
from collections import Counter
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import inch
from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

ROOT=Path(__file__).resolve().parents[1]; ARTIFACTS=ROOT/'research'/'artifacts'
NAVY=colors.HexColor('#10233f'); BLUE=colors.HexColor('#1f6feb'); LIME=colors.HexColor('#b7e35f'); MUTED=colors.HexColor('#55657a'); PALE=colors.HexColor('#edf4fb')
US_STATES=set('AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split())

def clean(v,f='Not stated'):
    if v is None or v=='': return f
    if isinstance(v,list): return ', '.join(clean(x,'') for x in v if x is not None)
    return str(v).replace('\u2013','-').replace('\u2014','-').replace('\u2011','-')

def load(p):
    if not p.exists(): raise SystemExit(f'Input snapshot not found: {p}')
    d=json.loads(p.read_text(encoding='utf-8'))
    if not isinstance(d,dict) or not isinstance(d.get('jobs'),list) or not isinstance(d.get('coverage'),list): raise SystemExit('Snapshot must contain jobs and coverage lists.')
    return d

def stats(d):
    jobs=d['jobs']; companies={clean(j.get('company'),'Unknown') for j in jobs}; roles=Counter(clean(j.get('roleFamily')) for j in jobs); levels=Counter(clean(j.get('experienceLevel'),'unspecified') for j in jobs); regions=Counter(); skills=Counter(); skill_companies={}; sources=Counter(clean(j.get('source')) for j in jobs)
    for j in jobs:
        labels={str(x.get('state') or '').strip().upper() for x in j.get('locations',[])} & US_STATES
        if j.get('remote'): labels.add('Remote - US')
        for x in labels: regions[x]+=1
        for n in {clean(x.get('name') if isinstance(x,dict) else x, '') for x in j.get('skills',[]) or []}:
            if n: skills[n]+=1; skill_companies.setdefault(n,set()).add(clean(j.get('company'),'Unknown'))
    return {'jobs':jobs,'companies':companies,'roles':roles,'levels':levels,'regions':regions,'skills':skills,'skill_companies':skill_companies,'coverage':d['coverage'],'sources':sources,'salary_count':sum(bool(j.get('salary')) for j in jobs)}

def styles():
    b=getSampleStyleSheet()
    return {'title':ParagraphStyle('T',parent=b['Title'],fontName='Helvetica-Bold',fontSize=19,leading=22,textColor=NAVY,spaceAfter=4),'sub':ParagraphStyle('S',parent=b['Normal'],fontSize=8.2,leading=10,textColor=MUTED,spaceAfter=6),'h':ParagraphStyle('H',parent=b['Heading2'],fontName='Helvetica-Bold',fontSize=9.7,leading=11.2,textColor=BLUE,spaceBefore=4,spaceAfter=2),'body':ParagraphStyle('B',parent=b['BodyText'],fontSize=9.2,leading=11.4,textColor=NAVY,spaceAfter=2),'small':ParagraphStyle('Sm',parent=b['BodyText'],fontSize=7.7,leading=9.1,textColor=NAVY)}

def footer(c,doc):
    c.saveState(); c.setStrokeColor(LIME); c.setLineWidth(2); c.line(doc.leftMargin,.43*inch,letter[0]-doc.rightMargin,.43*inch); c.setFont('Helvetica',6.6); c.setFillColor(MUTED); c.drawString(doc.leftMargin,.27*inch,'AI Career Compass | Project files'); c.drawRightString(letter[0]-doc.rightMargin,.27*inch,f'Page {doc.page}'); c.restoreState()

def pdf(path,title,subtitle,sections,d):
    st=styles(); s=stats(d); doc=SimpleDocTemplate(str(path),pagesize=letter,leftMargin=.56*inch,rightMargin=.56*inch,topMargin=.46*inch,bottomMargin=.56*inch)
    story=[Paragraph(html.escape(title),st['title']),Paragraph(html.escape(subtitle),st['sub'])]
    t=Table([[Paragraph('Snapshot',st['small']),Paragraph(clean(d.get('meta',{}).get('snapshotDate')),st['small'])],[Paragraph('Postings / companies',st['small']),Paragraph(f"{len(s['jobs'])} / {len(s['companies'])}",st['small'])],[Paragraph('Source checks',st['small']),Paragraph(str(len(s['coverage'])),st['small'])]],colWidths=[1.45*inch,1.9*inch],hAlign='LEFT'); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),.35,colors.HexColor('#c9d9ea')),('INNERGRID',(0,0),(-1,-1),.2,colors.white),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2)])); story += [t,Spacer(1,4)]
    for h,b in sections: story += [Paragraph(html.escape(h),st['h']),Paragraph(html.escape(b).replace('\n','<br/>'),st['body'])]
    doc.build(story,onFirstPage=footer,onLaterPages=footer)

def methodology(d,out):
    s=stats(d); src=', '.join(f'{k} ({v})' for k,v in sorted(s['sources'].items()))
    sections=[('Purpose and views','AI Career Compass supports Opportunity landscape for the filtered sample, Skill lab for local skill-mention exploration, and Job references for the full posting reference list. The reference list exposes experience, skills, direction, location, and source without an application channel.'),('Canonical snapshot',f"The snapshot contains {len(s['jobs'])} unique postings from {len(s['companies'])} companies and {len(s['coverage'])} company/source checks. Sources are {src}. Counts are postings, not headcount; source links, review labels, and data-quality notes remain available in the Project files downloads."),('Shared filters and measures','All three views share primary role direction, experience level, US region/state/remote, and graduate evidence. Job references adds posting search and a canonical skill-mention filter that can persist into the charts and Skill lab. Landscape reports distributions and a skill-demand matrix. Skill lab reports the count and fraction of filtered postings mentioning at least one selected skill by role, then previews before/after coverage when one skill is tried.'),('Experience labels','Experience level is one of four broad descriptive exploration buckets and is independent from graduate eligibility. Source evidence maps 0–2 years to entry; experienced individual contributors with 3+ years, supported independent scope, or a prior production track record to senior; explicit senior technical scope to staff; and people-management scope to manager. Ordinary experience familiarity alone is insufficient. Unsupported cases stay unspecified. The basis and explanation are recorded, while graduate flags and qualification paths are unchanged.'),('Skill interpretation','A posting counts once when it mentions at least one selected skill. Recommendations exclude selected skills and rank by posting mentions, then company breadth. Mention coverage is not proficiency, eligibility, readiness, hiring probability, or absence of an unmentioned skill. Automated extraction uses a fixed vocabulary.'),('Evidence and privacy','Records retain official URLs, source IDs, timestamps, extraction notes, and review level. The sample is non-representative and state/skill counts can overlap. Selected skills stay in page memory and optional device-local storage; they are not sent to a server. Public CSV downloads retain the evidence fields.')]
    pdf(out/'methodology.pdf','Methodology','AI Career Compass | visualizer rules and evidence boundaries',sections,d)

def reflection(d,out):
    s=stats(d); sections=[('Design decision',f"The product visualizes {len(s['jobs'])} public postings to support career exploration. Opportunity landscape describes where postings appear, Skill lab tests local skill mentions, and Job references keeps every posting inspectable by experience, skills, direction, location, and source."),('What the evidence supports','The filtered charts support descriptive questions about direction, experience, regions, and skill-mention coverage. All three views share role, experience, location, and graduate filters; Job references adds posting search and a canonical skill-mention filter that can carry into the charts and Skill lab. Official source links and Project files downloads preserve provenance.'),('What remains uncertain','This is a non-representative ATS sample. Automated skill extraction uses a fixed vocabulary, so tracked terms are overrepresented. Unknown skill is not skill absence, experience bucket is not graduate eligibility, and mention coverage is not proficiency or readiness. Early career evidence can require experience; it is kept separate from explicit graduate evidence.'),('AI assistance and privacy','AI assisted extraction, normalization, and copy review; source URLs, review labels, and limitations remain visible. Skill chips are local-only and optional device memory does not send a profile to a server. No applicant data or shortlist is collected.'),('Next iteration','Repeat collection with the same schema, add documented human adjudication for ambiguous skill mentions, and compare ranked recommendations against a written review sample. Keep the interface focused on evidence and learning prompts.')]
    pdf(out/'reflection.pdf','Reflection','AI Career Compass | short design reflection',sections,d)

def dictionary(d,out):
    s=stats(d); fields=[('id','Stable company-source identifier used for deduplication.'),('company / title / url','Employer, exact source title, and canonical official posting URL used by Job references.'),('source / sourceId / verifiedAt','ATS or company-careers provenance and latest source check timestamp.'),('roleFamily / tags','Primary direction used for one-category charts, plus additional technical directions.'),('locations / locationText / remote / workplace','Source-listed US places and stated work arrangement; state and remote counts can overlap.'),('newgradStatus / newgradEvidence','Graduate evidence group: explicit, zero-experience, early-career, or unclear, with source explanation.'),('experienceLevel / experienceLevelBasis / experienceLevelEvidence','Four descriptive exploration buckets: 0–2 entry; experienced individual contributor with 3+ years, independent scope, or prior production track record, senior; explicit senior technical scope, staff; people-management scope, manager. Unsupported evidence remains unspecified.'),('experienceEvidenceSource / requirementYears / classifiedRequirementYears','Official excerpt, URL and check date; all parsed numbers and the numeric floor used for a requirements bucket. These do not establish eligibility.'),('experienceReferences','Raw year mentions from the full description; never a validated scalar minimum.'),('skills','Mentioned skill names with required, preferred, or mentioned level. Skill lab counts a posting once per selected-skill set.'),('qualificationPaths','Degree and experience alternatives; unknown values stay unknown and are not converted to zero.'),('salary / sponsorship','Disclosed base-pay ranges and public sponsorship statement; missing disclosure is not a negative answer.'),('summary / aiEvidence / qualificationNote / reviewNote','Short factual evidence and review/provenance notes retained for source-grounded interpretation.'),('coverage','Company-level source check; inaccessible or incomplete sources are not treated as no qualifying jobs.'),('meta','Snapshot date, scope, unit, partitions, review description, and excluded count for reproducibility.')]
    lines=['# Data dictionary','',f"Generated from snapshot `{clean(d.get('meta',{}).get('snapshotDate'))}` with {len(s['jobs'])} postings and {len(s['companies'])} companies.",'','The unit is one unique public job posting. A posting may contain multiple locations, qualification paths, skills, or salary ranges.','','## Product measures','','- `direction distribution`: postings grouped by primary `roleFamily` or selected direction.','- `experience distribution`: postings grouped by four broad exploration buckets; unspecified remains visible when evidence is insufficient.','- `region distribution`: one count per listed state and a separate `Remote - US` bucket; totals can overlap.','- `skill-demand matrix`: postings mentioning a skill divided by filtered postings in the direction; one count per cell.','- `skill lab coverage`: filtered postings mentioning at least one selected skill, shown as count and fraction by role.','- `missing-skill recommendation`: unselected skills ranked by posting mentions, then company breadth; a learning suggestion.','','## Snapshot fields','','| Field | Meaning |','| --- | --- |']
    lines += [f'| `{n}` | {m} |' for n,m in fields]; lines += ['','Unknown values remain explicit (`null`, empty arrays, `Not stated`, or `unclear`). Absence of a skill mention does not establish that the job does not require it.','','## Provenance','',f"The snapshot has {len(s['coverage'])} source checks and {s['salary_count']} postings with disclosed salary. Official URLs and review labels are preserved in `dist/downloads/jobs.csv` and the published data snapshot."]
    (out/'data-dictionary.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

def demo(d,out):
    s=stats(d); top=s['skills'].most_common(1)[0][0] if s['skills'] else 'a selected skill'; lines=['# Five-minute demo script','','Use the deployed visualizer to demonstrate one student decision: which AI direction and skill to explore next.','','## 0:00-0:35 - Frame the sample',f"Open Opportunity landscape. Say: this is a dated, source-backed sample of {len(s['jobs'])} public US AI postings from {len(s['companies'])} companies. It describes the observed sample, not the entire labor market.",'','## 0:35-1:25 - Set the shared filters','Use primary role direction, experience level, US region/state/remote, and graduate evidence. Start with All, then choose one direction and Explicit graduate. Point out that all charts update to the selected sample. Reset graduate evidence to All before exploring skills.','','## 1:25-2:20 - Read Opportunity landscape','Show distributions by direction, experience, and region. Explain that state totals can overlap when one posting lists multiple places. Use the skill-demand matrix to answer which skills are mentioned across directions. This is mention coverage, not proficiency or eligibility.','','## 2:20-3:55 - Run Skill lab','Open Skill lab directly. Select local-only skill chips, optionally turn on Remember on this device, and show the fraction and count of filtered postings mentioning at least one selected skill by role. Add one skill to the selected set. Use Try one skill to show the before/after count of postings mentioning at least one selected skill. Choices stay in the browser and are not sent to a server.','','## 3:55-4:35 - Explain recommendations',f"Read missing-skill recommendations. They rank by posting mentions, then company breadth; read the current top unselected skill and its posting and company counts. Open the small suggested learning project template and explain that it is a preparation prompt, not a promise that the skill is required or that the project proves proficiency.",'','## 4:35-5:00 - Close with Job references','Open Job references. Point to the full posting reference list and its experience, skills, direction, location, and source fields, then use the compact Project files footer for CSV downloads, assignment materials, official provenance, and the one-page methodology. Close with the limits: non-representative ATS sample, unknown skill is not absence, and experience bucket is not graduate eligibility.']
    (out/'demo-script.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

def presentation(d,out):
    s=stats(d); snap=html.escape(clean(d.get('meta',{}).get('snapshotDate'))); rr=''.join(f'<tr><td>{html.escape(k)}</td><td>{v}</td></tr>' for k,v in s['roles'].most_common(6)); ll=''.join(f'<tr><td>{html.escape(k)}</td><td>{v}</td></tr>' for k,v in s['levels'].most_common()); tops=', '.join(f'{html.escape(k)} ({v})' for k,v in s['skills'].most_common(5)) or 'No skill mentions'
    slides=[f"<section><p class='eyebrow'>AI CAREER COMPASS</p><h1>A visualizer for the AI job landscape</h1><p class='lead'>Explore where postings appear, then test how selected skills change mention coverage.</p><div class='accent'></div><p class='meta'>Snapshot: {snap} | {len(s['jobs'])} postings | {len(s['companies'])} companies</p></section>",f"<section><p class='eyebrow'>01 / LANDSCAPE</p><h2>One shared filter bar</h2><div class='chips'><span>Direction</span><span>Experience level</span><span>US region / state / remote</span><span>Graduate evidence</span></div><p>Title and inferred experience buckets remain available. Graduate evidence is separate: All, Explicit graduate, or Early career.</p><div class='stat-grid'><div><b>{len(s['jobs'])}</b><small>postings</small></div><div><b>{len(s['companies'])}</b><small>companies</small></div><div><b>{len(s['coverage'])}</b><small>source checks</small></div></div></section>",f"<section><p class='eyebrow'>02 / LANDSCAPE</p><h2>Describe the sample at a glance</h2><div class='two-col'><div><h3>Primary direction</h3><table>{rr}</table></div><div><h3>Experience level</h3><table>{ll}</table></div></div><p class='note'>Experience buckets describe the sample and may be inferred from official requirements. They do not establish graduate eligibility.</p></section>",f"<section><p class='eyebrow'>03 / SKILL LAB</p><h2>Test a skill hypothesis locally</h2><p>Choose skill chips in the browser. Skill lab reports the fraction and count of filtered postings mentioning at least one selected skill by role.</p><div class='advice-list'><div class='advice'><b>Try one skill</b><span>Compare before and after posting coverage.</span></div><div class='advice'><b>Remember on this device</b><span>Optional local storage; selection is not sent to a server.</span></div><div class='advice'><b>Current high-mention examples</b><span>{tops}</span></div></div><p class='note'>A mention is evidence of text coverage, not proficiency, eligibility, readiness, or hiring probability.</p></section>","<section><p class='eyebrow'>04 / JOB REFERENCES</p><h2>Evidence stays inspectable</h2><ul><li>The full posting reference list shows experience, skills, direction, location, and source.</li><li>Search and canonical skill filters can carry into charts and Skill lab.</li><li>CSV exports preserve provenance and data-quality fields.</li><li>Unknown skill is not skill absence; experience bucket is not graduate eligibility.</li><li>Selected skills stay in the browser; device memory is optional.</li></ul><div class='accent'></div><a class='site-link' href='./#postings'>Open Job references ↗</a></section>"]
    body='\n'.join(slides); page=f"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>AI Career Compass presentation</title><style>:root{{--navy:#10233f;--blue:#1f6feb;--lime:#b7e35f;--ink:#17324d;--muted:#61758b;--paper:#f7fbff}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}}main{{min-height:100vh;display:grid;place-items:center;padding:3rem 3rem 6rem}}section{{display:none;width:min(960px,92vw);min-height:560px;padding:4rem 4.5rem;background:#fff;border:1px solid #d9e6f2;box-shadow:0 18px 60px #10233f14;border-radius:18px}}section.active{{display:block}}h1{{font-size:clamp(2.8rem,7vw,5.8rem);line-height:.98;letter-spacing:-.06em;color:var(--navy);max-width:750px;margin:.4rem 0 1.5rem}}h2{{font-size:clamp(2rem,4vw,3.2rem);line-height:1.05;letter-spacing:-.04em;color:var(--navy);margin:.5rem 0 2rem}}h3{{color:var(--navy);font-size:1rem;line-height:1.2;margin:.25rem 0 .7rem}}.eyebrow{{color:var(--blue);font-size:.78rem;font-weight:800;letter-spacing:.16em}}.lead{{font-size:1.35rem;max-width:650px;color:var(--muted)}}.meta,.note{{color:var(--muted);font-size:.9rem}}.accent{{width:100px;height:8px;background:var(--lime);border-radius:10px;margin:2rem 0}}.chips{{display:flex;flex-wrap:wrap;gap:.7rem;margin:1.5rem 0 2rem}}.chips span{{background:#eef6ff;padding:.7rem 1rem;border-radius:999px;color:var(--blue);font-weight:700}}.stat-grid{{display:flex;gap:1rem;margin:2rem 0}}.stat-grid div{{background:#eef6ff;border-radius:12px;padding:1rem 1.3rem;min-width:130px}}.stat-grid b{{display:block;font-size:2.2rem;color:var(--blue)}}.stat-grid small{{color:var(--muted)}}.two-col{{display:grid;grid-template-columns:1fr 1fr;gap:2rem}}table{{width:100%;border-collapse:collapse;margin:.5rem 0 1rem}}td{{text-align:left;border-bottom:1px solid #d9e6f2;padding:.55rem .45rem}}td:last-child{{text-align:right;color:var(--blue);font-weight:700}}.advice-list{{display:grid;gap:1rem;margin:1.5rem 0}}.advice{{display:grid;gap:.25rem;background:#eef6ff;border-left:5px solid var(--lime);padding:1rem 1.2rem;border-radius:0 10px 10px 0}}.advice b{{color:var(--navy)}}.advice span{{color:var(--muted)}}li{{margin:.8rem 0;font-size:1.05rem}}a{{color:var(--blue);font-weight:700}}.site-link{{display:inline-block;margin-top:1rem}}.deck-nav{{position:fixed;bottom:1rem;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:.75rem;background:#fff;border:1px solid #d9e6f2;border-radius:999px;padding:.45rem .65rem;box-shadow:0 8px 30px #10233f20;z-index:5}}.deck-nav button{{border:0;background:#eef6ff;color:var(--navy);border-radius:999px;padding:.55rem .9rem;font:inherit;cursor:pointer}}.deck-nav button:hover,.deck-nav button:focus{{background:var(--lime)}}#page-number{{min-width:3.5rem;text-align:center;color:var(--muted);font-variant-numeric:tabular-nums}}@media(max-width:650px){{main{{padding:1rem 1rem 5.5rem}}section{{padding:2rem;min-height:600px;width:96vw}}.two-col{{grid-template-columns:1fr}}.stat-grid{{flex-wrap:wrap}}.deck-nav{{width:max-content;max-width:calc(100vw - 2rem)}}}}</style></head><body><main id='deck'>{body}</main><nav class='deck-nav' aria-label='Presentation navigation'><button id='prev' type='button'>← Previous</button><span id='page-number'>1 / {len(slides)}</span><button id='next' type='button'>Next →</button></nav><script>const slides=[...document.querySelectorAll('section')],n=document.getElementById('page-number');let i=0;function show(x){{i=(x+slides.length)%slides.length;slides.forEach((s,k)=>s.classList.toggle('active',k===i));n.textContent=(i+1)+' / '+slides.length;location.hash='slide-'+(i+1)}}document.getElementById('prev').onclick=()=>show(i-1);document.getElementById('next').onclick=()=>show(i+1);document.onkeydown=e=>{{if(['ArrowRight',' ','PageDown'].includes(e.key)){{e.preventDefault();show(i+1)}}if(['ArrowLeft','PageUp'].includes(e.key)){{e.preventDefault();show(i-1)}}}};const h=Number(location.hash.replace('#slide-',''));show(Number.isFinite(h)&&h>0?h-1:0);</script></body></html>"""
    (out/'presentation.html').write_text(page,encoding='utf-8')

def main():
    p=argparse.ArgumentParser(); p.add_argument('--input',type=Path,default=ROOT/'dist'/'data.json'); p.add_argument('--output',type=Path,default=ARTIFACTS); a=p.parse_args(); d=load(a.input); a.output.mkdir(parents=True,exist_ok=True); methodology(d,a.output); reflection(d,a.output); dictionary(d,a.output); demo(d,a.output); presentation(d,a.output); print(f'Generated artifacts in {a.output}')
if __name__=='__main__': main()
